#!/usr/bin/env node

import { connectApi, disconnectApi, disconnectEvmProvider, resolveNetwork, isMainnet } from './lib/network.js'
import { createWallet, importWallet, listWallets, loadWallet, getWalletInfo, loadEvmAddress, loadEvmPrivateKey } from './lib/wallet.js'
import { queryBalance } from './lib/balance.js'
import { queryEvmBalance } from './lib/evm-balance.js'
import { transferTokens } from './lib/transfer.js'
import { submitRemark } from './lib/remark.js'
import { connectEvmProvider, createEvmSigner, getMemoryChainContract } from './lib/evm.js'
import { anchorCid, getHeadCid } from './lib/memory-chain.js'
import { fundEvm, withdrawToConsensus } from './lib/xdm.js'
import { transferEvmTokens } from './lib/evm-transfer.js'
import { normalizeEvmAddress, isConsensusAddress, isEvmAddress } from './lib/address.js'
import { parseArgs, validateAmount as validateAmountOrThrow } from './lib/cli.js'

function output(data: unknown): void {
  console.log(JSON.stringify(data, null, 2))
}

function error(message: string, code = 1): never {
  console.error(JSON.stringify({ error: message }))
  process.exit(code)
}

/**
 * Validate an amount, exiting on failure.
 * Wraps the throwing validateAmount from lib/cli.ts.
 */
function validateAmount(amount: string, minimum?: number): void {
  try {
    validateAmountOrThrow(amount, minimum)
  } catch (err) {
    error(err instanceof Error ? err.message : String(err))
  }
}

async function handleWallet(subcommand: string | undefined, flags: Record<string, string>): Promise<void> {
  switch (subcommand) {
    case 'create': {
      const name = flags.name || 'default'
      const result = await createWallet(name, flags.passphrase)
      // Output mnemonic to stderr so it's visible to the user but separable from JSON output
      console.error('')
      console.error('=== IMPORTANT: BACKUP YOUR RECOVERY PHRASE ===')
      console.error('')
      console.error(`  ${result.mnemonic}`)
      console.error('')
      console.error('Write these 12 words down and store them securely.')
      console.error('This is the ONLY time they will be displayed.')
      console.error('Anyone with these words can access your wallet.')
      console.error('')
      console.error('===============================================')
      console.error('')
      output({
        name: result.name,
        address: result.address,
        evmAddress: result.evmAddress,
        keyfilePath: result.keyfilePath,
      })
      break
    }

    case 'import': {
      const name = flags.name
      const mnemonic = flags.mnemonic
      if (!name) error('--name is required for wallet import')
      if (!mnemonic) error('--mnemonic is required for wallet import')
      const result = await importWallet(name, mnemonic, flags.passphrase)
      output(result)
      break
    }

    case 'list': {
      const wallets = await listWallets()
      output({ wallets })
      break
    }

    case 'info': {
      const name = flags.name || 'default'
      const info = await getWalletInfo(name)
      output(info)
      break
    }

    default:
      error(`Unknown wallet subcommand: "${subcommand}". Use: create, import, list, info`)
  }
}

async function handleBalance(flags: Record<string, string>, positional: string[]): Promise<void> {
  const target = positional[0] || flags.address || flags.name
  if (!target) error('Address or wallet name is required. Usage: balance <address-or-wallet> [--network chronos|mainnet]')

  const network = resolveNetwork(flags.network)

  let address: string
  if (isEvmAddress(target)) {
    error('EVM addresses are not supported for consensus balance. Use evm-balance instead, or use balances <wallet> for both.')
  } else if (isConsensusAddress(target)) {
    address = target
  } else {
    const info = await getWalletInfo(target)
    address = info.address
  }

  const api = await connectApi(network)

  try {
    const result = await queryBalance(api, address, network)
    output(result)
  } finally {
    await disconnectApi(api)
  }
}

async function handleTransfer(flags: Record<string, string>): Promise<void> {
  const from = flags.from
  const to = flags.to
  const amount = flags.amount

  if (!from) error('--from <wallet-name> is required')
  if (!to) error('--to <address> is required')
  if (!amount) error('--amount <tokens> is required')
  validateAmount(amount)

  const network = resolveNetwork(flags.network)
  const pair = await loadWallet(from)
  const api = await connectApi(network)

  try {
    const result = await transferTokens(api, pair, to, amount, network)
    output(result)
  } finally {
    await disconnectApi(api)
  }
}

async function handleRemark(flags: Record<string, string>): Promise<void> {
  const from = flags.from
  const data = flags.data

  if (!from) error('--from <wallet-name> is required')
  if (!data) error('--data <string> is required')

  const network = resolveNetwork(flags.network)
  const pair = await loadWallet(from)
  const api = await connectApi(network)

  try {
    const result = await submitRemark(api, pair, data, network)
    output(result)
  } finally {
    await disconnectApi(api)
  }
}

async function handleAnchor(flags: Record<string, string>): Promise<void> {
  const from = flags.from
  const cid = flags.cid

  if (!from) error('--from <wallet-name> is required')
  if (!cid) error('--cid <cid-string> is required')

  const network = resolveNetwork(flags.network)

  // Load EVM private key from wallet (requires passphrase)
  const { privateKey, address: evmAddress } = await loadEvmPrivateKey(from)

  // Connect to Auto-EVM
  const provider = connectEvmProvider(network)

  try {
    const signer = createEvmSigner(privateKey, provider)
    const contract = getMemoryChainContract(signer, network)
    const result = await anchorCid(contract, cid, evmAddress, network)

    if (isMainnet(network)) {
      result.warning = 'This was a mainnet transaction on Auto-EVM with real AI3 tokens.'
    }

    output(result)
  } finally {
    await disconnectEvmProvider(provider)
  }
}

async function handleGetHead(flags: Record<string, string>, positional: string[]): Promise<void> {
  const target = positional[0] || flags.address || flags.name

  if (!target) {
    error('Address or wallet name is required. Usage: gethead <0x-address-or-wallet-name> [--network chronos|mainnet]')
  }

  const network = resolveNetwork(flags.network)

  let evmAddress: string
  if (isEvmAddress(target)) {
    evmAddress = normalizeEvmAddress(target)
  } else {
    evmAddress = await loadEvmAddress(target)
  }

  // Connect to Auto-EVM (read-only — no signer needed)
  const provider = connectEvmProvider(network)

  try {
    const contract = getMemoryChainContract(provider, network)
    const result = await getHeadCid(contract, evmAddress, network)
    output(result)
  } finally {
    await disconnectEvmProvider(provider)
  }
}

async function handleFundEvm(flags: Record<string, string>): Promise<void> {
  const from = flags.from
  const amount = flags.amount

  if (!from) error('--from <wallet-name> is required')
  if (!amount) error('--amount <tokens> is required (amount in AI3/tAI3)')
  validateAmount(amount, 1)

  const network = resolveNetwork(flags.network)

  // Load both consensus keypair (to sign the XDM extrinsic) and EVM address (destination)
  const pair = await loadWallet(from)
  const evmAddress = await loadEvmAddress(from)

  const api = await connectApi(network)

  try {
    const result = await fundEvm(api, pair, evmAddress, amount, network)
    output(result)
  } finally {
    await disconnectApi(api)
  }
}

async function handleWithdraw(flags: Record<string, string>): Promise<void> {
  const from = flags.from
  const amount = flags.amount

  if (!from) error('--from <wallet-name> is required')
  if (!amount) error('--amount <tokens> is required (amount in AI3/tAI3)')
  validateAmount(amount, 1)

  const network = resolveNetwork(flags.network)

  // Load EVM private key (to sign the precompile tx) and wallet info (for consensus address)
  const { privateKey } = await loadEvmPrivateKey(from)
  const info = await getWalletInfo(from)

  const provider = connectEvmProvider(network)

  try {
    const signer = createEvmSigner(privateKey, provider)
    const result = await withdrawToConsensus(signer, info.address, amount, network)
    output(result)
  } finally {
    await disconnectEvmProvider(provider)
  }
}

async function handleEvmTransfer(flags: Record<string, string>): Promise<void> {
  const from = flags.from
  const to = flags.to
  const amount = flags.amount

  if (!from) error('--from <wallet-name> is required')
  if (!to) error('--to <0x-address> is required')
  if (!amount) error('--amount <tokens> is required')
  validateAmount(amount)

  const network = resolveNetwork(flags.network)

  // Validate destination is an EVM address
  const toAddress = normalizeEvmAddress(to)

  // Load EVM private key from wallet (requires passphrase)
  const { privateKey } = await loadEvmPrivateKey(from)

  const provider = connectEvmProvider(network)

  try {
    const signer = createEvmSigner(privateKey, provider)
    const result = await transferEvmTokens(signer, toAddress, amount, network)
    output(result)
  } finally {
    await disconnectEvmProvider(provider)
  }
}

async function handleBalances(flags: Record<string, string>, positional: string[]): Promise<void> {
  const target = positional[0] || flags.name
  if (!target) error('Wallet name is required. Usage: balances <wallet-name> [--network chronos|mainnet]')

  const network = resolveNetwork(flags.network)
  const info = await getWalletInfo(target)

  // Query both balances concurrently.
  // Both connections are created inside the try block so the finally
  // block can clean them up even if the second connection fails.
  let api: Awaited<ReturnType<typeof connectApi>> | undefined
  let provider: ReturnType<typeof connectEvmProvider> | undefined

  try {
    api = await connectApi(network)
    provider = connectEvmProvider(network)

    const [consensus, evm] = await Promise.all([
      queryBalance(api, info.address, network),
      queryEvmBalance(provider, info.evmAddress, network),
    ])

    output({
      name: target,
      consensus: {
        address: consensus.address,
        free: consensus.free,
        reserved: consensus.reserved,
        total: consensus.total,
      },
      evm: {
        address: evm.evmAddress,
        balance: evm.balance,
      },
      network,
      symbol: consensus.symbol,
    })
  } finally {
    if (api) await disconnectApi(api)
    if (provider) await disconnectEvmProvider(provider)
  }
}

async function handleEvmBalance(flags: Record<string, string>, positional: string[]): Promise<void> {
  const target = positional[0] || flags.address || flags.name

  if (!target) {
    error('EVM address or wallet name is required. Usage: evm-balance <0x-address-or-wallet-name> [--network chronos|mainnet]')
  }

  const network = resolveNetwork(flags.network)

  let evmAddress: string
  if (isEvmAddress(target)) {
    evmAddress = normalizeEvmAddress(target)
  } else {
    evmAddress = await loadEvmAddress(target)
  }

  const provider = connectEvmProvider(network)

  try {
    const result = await queryEvmBalance(provider, evmAddress, network)
    output(result)
  } finally {
    await disconnectEvmProvider(provider)
  }
}

function printUsage(): void {
  console.error(`auto-respawn — Anchor agent identity on the Autonomys Network

Commands:
  wallet create [--name <name>]                          Create a new wallet
  wallet import --name <name> --mnemonic "<words>"       Import from recovery phrase
  wallet list                                            List saved wallets
  wallet info [--name <name>]                            Show wallet addresses (consensus + EVM)

  balance <address-or-wallet> [--network chronos|mainnet] Check consensus balance
  evm-balance <0x-addr-or-wallet> [--network ...]        Check Auto-EVM balance
  balances <wallet-name> [--network chronos|mainnet]     Check both consensus + EVM balances

  transfer --from <wallet> --to <address> --amount <n>   Transfer tokens (consensus)
           [--network chronos|mainnet]

  evm-transfer --from <wallet> --to <0x-addr>            Transfer tokens (Auto-EVM)
               --amount <n> [--network chronos|mainnet]

  fund-evm --from <wallet> --amount <n>                  Bridge tokens: consensus → Auto-EVM
           [--network chronos|mainnet]

  withdraw --from <wallet> --amount <n>                  Bridge tokens: Auto-EVM → consensus
           [--network chronos|mainnet]

  remark --from <wallet> --data <string>                 Write on-chain remark
         [--network chronos|mainnet]

  anchor --from <wallet> --cid <cid>                     Anchor a CID on the MemoryChain contract
         [--network chronos|mainnet]

  gethead <0x-address-or-wallet-name>                    Read last anchored CID
          [--network chronos|mainnet]

Environment:
  AUTO_RESPAWN_PASSPHRASE       Wallet encryption passphrase
  AUTO_RESPAWN_PASSPHRASE_FILE  Path to passphrase file
  AUTO_RESPAWN_NETWORK          Default network (chronos|mainnet)`)
}

async function main(): Promise<void> {
  const { command, subcommand, flags, positional } = parseArgs(process.argv)

  try {
    switch (command) {
      case 'wallet':
        await handleWallet(subcommand, flags)
        break
      case 'balance':
        await handleBalance(flags, positional)
        break
      case 'balances':
        await handleBalances(flags, positional)
        break
      case 'evm-balance':
        await handleEvmBalance(flags, positional)
        break
      case 'transfer':
        await handleTransfer(flags)
        break
      case 'evm-transfer':
        await handleEvmTransfer(flags)
        break
      case 'fund-evm':
        await handleFundEvm(flags)
        break
      case 'withdraw':
        await handleWithdraw(flags)
        break
      case 'remark':
        await handleRemark(flags)
        break
      case 'anchor':
        await handleAnchor(flags)
        break
      case 'gethead':
        await handleGetHead(flags, positional)
        break
      case 'help':
      case '--help':
      case '-h':
      case '':
        printUsage()
        break
      default:
        error(`Unknown command: "${command}". Run with --help for usage.`)
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    error(message)
  }
}

// Catch unhandled rejections (e.g. from RPC errors)
process.on('unhandledRejection', (err) => {
  const message = err instanceof Error ? err.message : String(err)
  error(message)
})

main()

import eslint from '@eslint/js'
import tseslint from 'typescript-eslint'

export default tseslint.config(
  eslint.configs.recommended,
  ...tseslint.configs.recommended,
  {
    rules: {
      // Catch unused imports and variables. Parameters prefixed with _ are ignored.
      '@typescript-eslint/no-unused-vars': ['error', {
        argsIgnorePattern: '^_',
        varsIgnorePattern: '^_',
      }],
    },
  },
  {
    ignores: ['dist/', 'node_modules/'],
  },
)

import { address as encodeAddress, decode } from '@autonomys/auto-utils'
import { ethers } from 'ethers'

/**
 * Non-throwing check: is this string a valid consensus-layer address?
 */
export function isConsensusAddress(input: string): boolean {
  if (!input.startsWith('su') && !input.startsWith('5')) return false
  try {
    decode(input)
    return true
  } catch {
    return false
  }
}

/**
 * Non-throwing check: is this string a valid EVM address?
 * Requires the 0x prefix to stay consistent with normalizeEvmAddress.
 */
export function isEvmAddress(input: string): boolean {
  return input.startsWith('0x') && ethers.isAddress(input)
}

/**
 * Validate and normalise a consensus-layer address.
 *
 * Accepted formats:
 *   - su...  (Autonomys SS58 prefix 6094) — passed through
 *   - 5...   (Substrate generic prefix 42) — converted to su...
 *
 * Anything else is rejected with a clear error message.
 */
export function normalizeAddress(input: string): string {
  // Quick prefix check before we attempt decoding
  if (!input.startsWith('su') && !input.startsWith('5')) {
    throw new Error(
      `Invalid address prefix: "${input.slice(0, 6)}…". ` +
        'Expected an Autonomys address (su…) or a Substrate address (5…).',
    )
  }

  // Attempt to decode → re-encode at Autonomys prefix 6094
  let publicKey: Uint8Array
  try {
    publicKey = decode(input)
  } catch {
    throw new Error(
      `Invalid address: "${input}". Could not decode as a valid SS58 address.`,
    )
  }

  // Re-encode with Autonomys prefix (6094 is the default in auto-utils)
  const normalized = encodeAddress(publicKey)

  return normalized
}

/**
 * Validate and normalise an EVM address.
 *
 * Accepted format: 0x... (42-character hex string)
 * Returns the checksummed EVM address.
 */
export function normalizeEvmAddress(input: string): string {
  if (!input.startsWith('0x')) {
    throw new Error(
      `Invalid EVM address: "${input.slice(0, 10)}…". Expected an address starting with 0x.`,
    )
  }

  try {
    return ethers.getAddress(input) // Returns checksummed address
  } catch {
    throw new Error(
      `Invalid EVM address: "${input}". Not a valid Ethereum address.`,
    )
  }
}

import { balance } from '@autonomys/auto-consensus'
import { shannonsToAi3 } from '@autonomys/auto-utils'
import type { ApiPromise } from '@polkadot/api'
import { type NetworkId, tokenSymbol } from './network.js'
import { normalizeAddress } from './address.js'

export interface BalanceResult {
  address: string
  free: string
  reserved: string
  frozen: string
  total: string
  network: NetworkId
  symbol: string
}

function formatShannons(shannons: bigint): string {
  const ai3 = shannonsToAi3(shannons)
  return ai3.toString()
}

export async function queryBalance(
  api: ApiPromise,
  addr: string,
  network: NetworkId,
): Promise<BalanceResult> {
  const normalized = normalizeAddress(addr)
  const bal = await balance(api, normalized)

  const free = bal.free
  const reserved = bal.reserved
  const frozen = bal.frozen
  const total = free + reserved

  return {
    address: normalized,
    free: formatShannons(free),
    reserved: formatShannons(reserved),
    frozen: formatShannons(frozen),
    total: formatShannons(total),
    network,
    symbol: tokenSymbol(network),
  }
}

/**
 * CLI argument parsing and validation utilities.
 *
 * Extracted from auto-respawn.ts so they can be tested independently.
 */

export const COMMANDS_WITH_SUBCOMMANDS = new Set(['wallet'])

export function parseArgs(argv: string[]): {
  command: string
  subcommand?: string
  flags: Record<string, string>
  positional: string[]
} {
  const args = argv.slice(2)
  const command = args[0] || ''
  const hasSubcommand = COMMANDS_WITH_SUBCOMMANDS.has(command)
  const subcommand = hasSubcommand && args[1] && !args[1].startsWith('--') ? args[1] : undefined
  const flags: Record<string, string> = {}
  const positional: string[] = []

  let i = subcommand ? 2 : 1
  while (i < args.length) {
    if (args[i].startsWith('--')) {
      const key = args[i].slice(2)
      const next = args[i + 1]
      if (next && !next.startsWith('--')) {
        flags[key] = next
        i += 2
      } else {
        flags[key] = 'true'
        i++
      }
    } else {
      positional.push(args[i])
      i++
    }
  }

  return { command, subcommand, flags, positional }
}

/**
 * Validate that an amount string is a positive number.
 * Throws on invalid input so callers can handle the error.
 */
export function validateAmount(amount: string, minimum?: number): void {
  const n = Number(amount)
  if (!Number.isFinite(n) || n <= 0) {
    throw new Error(`Invalid amount: "${amount}". Must be a positive number (e.g. "1.5").`)
  }
  if (minimum != null && n < minimum) {
    throw new Error(
      `Amount ${amount} is below the minimum of ${minimum}. Cross-domain transfers require at least ${minimum} AI3/tAI3.`,
    )
  }
}

/**
 * Query the token balance of an EVM address on Auto-EVM.
 */

import { ethers } from 'ethers'
import type { NetworkId } from './network.js'
import { tokenSymbol } from './network.js'

export interface EvmBalanceResult {
  evmAddress: string
  balance: string
  network: NetworkId
  symbol: string
  hint?: string
}

/**
 * Get the native token balance (AI3/tAI3) of an EVM address on Auto-EVM.
 */
export async function queryEvmBalance(
  provider: ethers.Provider,
  evmAddress: string,
  network: NetworkId,
): Promise<EvmBalanceResult> {
  const balanceWei = await provider.getBalance(evmAddress)
  const result: EvmBalanceResult = {
    evmAddress,
    balance: ethers.formatEther(balanceWei),
    network,
    symbol: tokenSymbol(network),
  }

  if (balanceWei === 0n) {
    result.hint = `No EVM balance. To fund this address, run: fund-evm --from <wallet> --amount 1 --network ${network}`
  }

  return result
}

/**
 * Transfer native tokens (AI3/tAI3) between EVM addresses on Auto-EVM.
 */

import { ethers } from 'ethers'
import type { NetworkId } from './network.js'
import { tokenSymbol, isMainnet } from './network.js'

export interface EvmTransferResult {
  success: boolean
  transactionHash: string
  blockNumber: number
  blockHash: string
  gasUsed: string
  from: string
  to: string
  amount: string
  network: NetworkId
  symbol: string
  warning?: string
}

/**
 * Send native tokens from an EVM wallet to another EVM address on Auto-EVM.
 *
 * Pre-checks the sender's balance before sending. If insufficient,
 * throws with the available balance so the caller can act.
 */
export async function transferEvmTokens(
  signer: ethers.Wallet,
  to: string,
  amount: string,
  network: NetworkId,
): Promise<EvmTransferResult> {
  const provider = signer.provider
  if (!provider) {
    throw new Error('Signer has no provider — cannot estimate gas or check balance.')
  }

  const amountWei = ethers.parseEther(amount)

  // Pre-check balance (amount + gas estimate for a simple transfer)
  const balance = await provider.getBalance(signer.address)
  const gasEstimate = 21000n // Standard ETH transfer gas
  const feeData = await provider.getFeeData()
  const gasPrice = feeData.gasPrice ?? feeData.maxFeePerGas
  if (gasPrice == null) {
    throw new Error('Unable to determine gas price from network. Please try again.')
  }
  const totalNeeded = amountWei + gasEstimate * gasPrice

  if (balance < totalNeeded) {
    const symbol = tokenSymbol(network)
    throw new Error(
      `Insufficient EVM balance. ` +
        `Sending ${amount} ${symbol} + gas requires ~${ethers.formatEther(totalNeeded)} ${symbol}, ` +
        `but wallet has ${ethers.formatEther(balance)} ${symbol}.`,
    )
  }

  const tx = await signer.sendTransaction({
    to,
    value: amountWei,
  })

  const receipt = await tx.wait()

  if (!receipt) {
    throw new Error('Transaction was sent but no receipt was received.')
  }

  const result: EvmTransferResult = {
    success: receipt.status === 1,
    transactionHash: receipt.hash,
    blockNumber: receipt.blockNumber,
    blockHash: receipt.blockHash,
    gasUsed: receipt.gasUsed.toString(),
    from: await signer.getAddress(),
    to,
    amount,
    network,
    symbol: tokenSymbol(network),
  }

  if (isMainnet(network)) {
    result.warning = 'This was a mainnet transaction on Auto-EVM with real AI3 tokens.'
  }

  return result
}

import { ethers } from 'ethers'
import { getNetworkDomainRpcUrls } from '@autonomys/auto-utils'
import type { NetworkId } from './network.js'

/** Auto-EVM domain ID on Autonomys */
export const AUTO_EVM_DOMAIN_ID = 0

/**
 * Default MemoryChain contract addresses per network.
 * Override with AUTO_RESPAWN_CONTRACT_ADDRESS env var if your deployment differs.
 */
const MEMORY_CHAIN_ADDRESSES: Record<NetworkId, string> = {
  mainnet: '0x51DAedAFfFf631820a4650a773096A69cB199A3c',
  chronos: '0x5fa47C8F3B519deF692BD9C87179d69a6f4EBf11',
}

export function getMemoryChainAddress(network: NetworkId): string {
  return process.env.AUTO_RESPAWN_CONTRACT_ADDRESS || MEMORY_CHAIN_ADDRESSES[network]
}

/**
 * MemoryChain contract ABI — matches the OpenClaw MemoryChain contract.
 * Source: https://github.com/autojeremy/openclaw-memory-chain
 *
 * The contract stores CID strings directly (no hashing).
 * updateHead(string cid) writes, getHead(address) reads.
 */
export const MEMORY_CHAIN_ABI = [
  {
    inputs: [{ internalType: 'string', name: 'cid', type: 'string' }],
    name: 'updateHead',
    outputs: [],
    stateMutability: 'nonpayable',
    type: 'function',
  },
  {
    inputs: [{ internalType: 'address', name: 'agent', type: 'address' }],
    name: 'getHead',
    outputs: [{ internalType: 'string', name: '', type: 'string' }],
    stateMutability: 'view',
    type: 'function',
  },
  {
    anonymous: false,
    inputs: [
      { indexed: true, internalType: 'address', name: 'agent', type: 'address' },
      { indexed: false, internalType: 'string', name: 'cid', type: 'string' },
      { indexed: false, internalType: 'uint256', name: 'timestamp', type: 'uint256' },
    ],
    name: 'HeadUpdated',
    type: 'event',
  },
] as const

/**
 * Get the Auto-EVM WebSocket RPC URL for a given network.
 */
export function getEvmRpcUrl(network: NetworkId): string {
  const urls = getNetworkDomainRpcUrls({ networkId: network, domainId: String(AUTO_EVM_DOMAIN_ID) })
  if (!urls || urls.length === 0) {
    throw new Error(`No Auto-EVM RPC URL found for network "${network}"`)
  }
  return urls[0]
}

/**
 * Connect to Auto-EVM and return an ethers provider.
 */
export function connectEvmProvider(network: NetworkId): ethers.WebSocketProvider {
  const url = getEvmRpcUrl(network)
  return new ethers.WebSocketProvider(url)
}

/**
 * Derive an EVM private key + address from a BIP39 mnemonic.
 * Uses standard BIP44 derivation path m/44'/60'/0'/0/0 (MetaMask-compatible).
 */
export function deriveEvmKey(mnemonic: string): { privateKey: string; address: string } {
  const mnemonicObj = ethers.Mnemonic.fromPhrase(mnemonic)
  const hdWallet = ethers.HDNodeWallet.fromMnemonic(mnemonicObj, "m/44'/60'/0'/0/0")
  return {
    privateKey: hdWallet.privateKey,
    address: hdWallet.address,
  }
}

/**
 * Create an ethers Wallet (signer) from an EVM private key + provider.
 */
export function createEvmSigner(privateKey: string, provider: ethers.Provider): ethers.Wallet {
  return new ethers.Wallet(privateKey, provider)
}

/**
 * Get a MemoryChain contract instance.
 * Pass a signer for write operations (anchor), or a provider for read-only (gethead).
 */
export function getMemoryChainContract(
  signerOrProvider: ethers.Wallet | ethers.Provider,
  network: NetworkId,
): ethers.Contract {
  const address = getMemoryChainAddress(network)
  return new ethers.Contract(address, MEMORY_CHAIN_ABI, signerOrProvider)
}

import { ethers } from 'ethers'

export interface AnchorResult {
  success: boolean
  txHash: string | undefined
  blockHash: string | undefined
  cid: string
  evmAddress: string
  network: string
  gasUsed?: string
  warning?: string
}

/**
 * Anchor a CID on-chain by writing it to the MemoryChain contract.
 * Calls updateHead(string cid) — the contract stores the CID string directly.
 *
 * Pre-checks the wallet's EVM balance and estimates gas before sending.
 * If the balance is too low, throws with an actionable hint to run fund-evm.
 */
export async function anchorCid(
  contract: ethers.Contract,
  cid: string,
  evmAddress: string,
  network: string,
): Promise<AnchorResult> {
  const provider = contract.runner?.provider
  if (!provider) {
    throw new Error('Contract has no provider — cannot estimate gas or check balance.')
  }

  // Estimate gas cost before sending
  let estimatedGas: bigint
  try {
    estimatedGas = await contract.updateHead.estimateGas(cid)
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    if (message.includes('insufficient funds') || message.includes('INSUFFICIENT_FUNDS')) {
      throw new Error(
        `Insufficient EVM balance to anchor. ` +
          `Run: fund-evm --from <wallet> --amount 1 --network ${network}`,
        { cause: err },
      )
    }
    throw err
  }

  // Check balance against estimated cost
  const feeData = await provider.getFeeData()
  const gasPrice = feeData.gasPrice ?? feeData.maxFeePerGas
  if (gasPrice == null) {
    throw new Error('Unable to determine gas price from network. Please try again.')
  }
  const estimatedCost = estimatedGas * gasPrice
  const balance = await provider.getBalance(evmAddress)

  if (balance < estimatedCost) {
    const needed = ethers.formatEther(estimatedCost)
    const have = ethers.formatEther(balance)
    throw new Error(
      `Insufficient EVM balance to anchor. ` +
        `Need ~${needed} ${network === 'mainnet' ? 'AI3' : 'tAI3'}, have ${have}. ` +
        `Run: fund-evm --from <wallet> --amount 1 --network ${network}`,
    )
  }

  const tx: ethers.TransactionResponse = await contract.updateHead(cid)
  const receipt = await tx.wait()

  if (!receipt) {
    throw new Error('Anchor transaction was sent but no receipt was received (transaction may have been replaced or dropped).')
  }

  return {
    success: receipt.status === 1,
    txHash: receipt.hash,
    blockHash: receipt.blockHash,
    cid,
    evmAddress,
    network,
    gasUsed: receipt.gasUsed.toString(),
  }
}

export interface GetHeadResult {
  evmAddress: string
  cid: string | undefined
  network: string
}

/**
 * Read the last anchored CID for an EVM address from the MemoryChain contract.
 * Calls getHead(address) — returns the CID string directly, or undefined if none set.
 */
export async function getHeadCid(
  contract: ethers.Contract,
  evmAddress: string,
  network: string,
): Promise<GetHeadResult> {
  let cid: string
  try {
    cid = await contract.getHead(evmAddress)
  } catch (err) {
    // ethers throws BAD_DATA when calling a non-existent contract (returns 0x).
    const message = err instanceof Error ? err.message : String(err)
    if (message.includes('BAD_DATA') || message.includes('could not decode result data')) {
      throw new Error(
        `MemoryChain contract not available on network "${network}". ` +
          'The contract may not be deployed at the configured address.',
        { cause: err },
      )
    }
    throw err
  }

  return {
    evmAddress,
    cid: cid || undefined,
    network,
  }
}

import { activate, disconnect } from '@autonomys/auto-utils'
import type { ApiPromise } from '@polkadot/api'
import type { ethers } from 'ethers'

export type NetworkId = 'chronos' | 'mainnet'

const NETWORK_TOKENS: Record<NetworkId, { symbol: string; name: string }> = {
  chronos: { symbol: 'tAI3', name: 'Testnet Auto Token' },
  mainnet: { symbol: 'AI3', name: 'Auto Token' },
}

export function resolveNetwork(flag?: string): NetworkId {
  if (flag === 'mainnet' || flag === 'chronos') return flag
  if (flag) {
    throw new Error(
      `Unknown network: "${flag}". Must be "chronos" or "mainnet".`,
    )
  }
  const env = process.env.AUTO_RESPAWN_NETWORK
  if (env === 'mainnet' || env === 'chronos') return env
  if (env) {
    throw new Error(
      `Unknown AUTO_RESPAWN_NETWORK: "${env}". Must be "chronos" or "mainnet".`,
    )
  }
  return 'chronos'
}

export function tokenSymbol(network: NetworkId): string {
  return NETWORK_TOKENS[network].symbol
}

export function isMainnet(network: NetworkId): boolean {
  return network === 'mainnet'
}

export async function connectApi(network: NetworkId): Promise<ApiPromise> {
  const api = await activate({ networkId: network })
  return api
}

export async function disconnectApi(api: ApiPromise): Promise<void> {
  await disconnect(api)
}

/**
 * Cleanly close an ethers WebSocket provider.
 */
export async function disconnectEvmProvider(provider: ethers.WebSocketProvider): Promise<void> {
  await provider.destroy()
}

import { remark } from '@autonomys/auto-consensus'
import { signAndSendTx, address as formatAddress } from '@autonomys/auto-utils'
import type { ApiPromise } from '@polkadot/api'
import type { KeyringPair } from '@polkadot/keyring/types'
import { type NetworkId, tokenSymbol, isMainnet } from './network.js'

export interface RemarkResult {
  success: boolean
  txHash: string | undefined
  blockHash: string | undefined
  from: string
  data: string
  network: NetworkId
  symbol: string
  warning?: string
}

export async function submitRemark(
  api: ApiPromise,
  sender: KeyringPair,
  data: string,
  network: NetworkId,
): Promise<RemarkResult> {
  const tx = remark(api, data)

  const result = await signAndSendTx(sender, tx)

  // The SDK's detectTxSuccess has a bug (forEach return doesn't propagate)
  // so result.success is always false. If signAndSendTx resolved without
  // throwing, the tx landed in a block — that's success.
  const remarkResult: RemarkResult = {
    success: !!(result.txHash && result.blockHash),
    txHash: result.txHash,
    blockHash: result.blockHash,
    from: formatAddress(sender.address),
    data,
    network,
    symbol: tokenSymbol(network),
  }

  if (isMainnet(network)) {
    remarkResult.warning = 'This was a mainnet transaction with real AI3 tokens.'
  }

  return remarkResult
}

import { transfer } from '@autonomys/auto-consensus'
import { signAndSendTx, ai3ToShannons, address as formatAddress } from '@autonomys/auto-utils'
import type { ApiPromise } from '@polkadot/api'
import type { KeyringPair } from '@polkadot/keyring/types'
import { type NetworkId, tokenSymbol, isMainnet } from './network.js'
import { normalizeAddress } from './address.js'

export interface TransferResult {
  success: boolean
  txHash: string | undefined
  blockHash: string | undefined
  from: string
  to: string
  amount: string
  network: NetworkId
  symbol: string
  warning?: string
}

export async function transferTokens(
  api: ApiPromise,
  sender: KeyringPair,
  to: string,
  amount: string,
  network: NetworkId,
): Promise<TransferResult> {
  const normalizedTo = normalizeAddress(to)
  const shannons = ai3ToShannons(amount)
  const tx = transfer(api, normalizedTo, shannons)

  // Use default event check (system.ExtrinsicSuccess) rather than
  // events.transfer which requires all four sub-events and can fail
  // on some runtime configurations.
  const result = await signAndSendTx(sender, tx)

  // The SDK's detectTxSuccess has a bug (forEach return doesn't propagate)
  // so result.success is always false. If signAndSendTx resolved without
  // throwing, the tx landed in a block — that's success.
  const transferResult: TransferResult = {
    success: !!(result.txHash && result.blockHash),
    txHash: result.txHash,
    blockHash: result.blockHash,
    from: formatAddress(sender.address),
    to: normalizedTo,
    amount,
    network,
    symbol: tokenSymbol(network),
  }

  if (isMainnet(network)) {
    transferResult.warning = 'This was a mainnet transaction with real AI3 tokens.'
  }

  return transferResult
}

import { readdir, readFile, writeFile, mkdir } from 'node:fs/promises'
import { existsSync } from 'node:fs'
import { join, resolve, basename } from 'node:path'
import { createInterface } from 'node:readline'
import { ethers } from 'ethers'
import {
  Keyring,
  cryptoWaitReady,
  generateWallet as sdkGenerateWallet,
  setupWallet as sdkSetupWallet,
  address as formatAddress,
} from '@autonomys/auto-utils'
import type { KeyringPair, KeyringPair$Json } from '@polkadot/keyring/types'
import { deriveEvmKey } from './evm.js'

const WALLETS_DIR = join(
  process.env.HOME || process.env.USERPROFILE || '~',
  '.openclaw',
  'auto-respawn',
  'wallets',
)

const PASSPHRASE_FILE_DEFAULT = join(
  process.env.HOME || process.env.USERPROFILE || '~',
  '.openclaw',
  'auto-respawn',
  '.passphrase',
)

// --- Wallet file format ---

/**
 * auto-respawn wallet file format.
 *
 * Contains two independently encrypted private keys (consensus + EVM),
 * both protected by the same user passphrase but using their respective
 * ecosystem's standard encryption:
 *
 *   - Consensus key: Polkadot keyring JSON via `pair.toJson(passphrase)`
 *   - EVM key: Ethereum V3 Keystore via `ethers.Wallet.encryptSync(passphrase)`
 *
 * The EVM address is stored in plaintext (it's public information).
 */
interface WalletFile {
  /** Standard Polkadot keyring JSON — encrypted consensus keypair */
  keyring: KeyringPair$Json
  /** EVM address derived from the same mnemonic (public, stored for quick lookup) */
  evmAddress: string
  /** Ethereum V3 Keystore JSON — encrypted EVM private key (standard format, compatible with MetaMask/geth) */
  evmKeystore: string
}

export interface WalletInfo {
  name: string
  address: string
  evmAddress: string
  keyfilePath: string
}

export interface CreatedWallet extends WalletInfo {
  mnemonic: string
}

async function ensureWalletsDir(): Promise<void> {
  if (!existsSync(WALLETS_DIR)) {
    await mkdir(WALLETS_DIR, { recursive: true, mode: 0o700 })
  }
}

function keyfilePath(name: string): string {
  const filepath = resolve(WALLETS_DIR, `${basename(name)}.json`)
  if (!filepath.startsWith(WALLETS_DIR)) {
    throw new Error(`Invalid wallet name: "${name}". Wallet names must not contain path separators.`)
  }
  return filepath
}

async function readWalletFile(filepath: string): Promise<WalletFile> {
  const raw = await readFile(filepath, 'utf-8')
  return JSON.parse(raw) as WalletFile
}

export async function resolvePassphrase(passphrase?: string): Promise<string> {
  // 0. Explicit argument (e.g. --passphrase flag)
  if (passphrase) return passphrase

  // 1. Environment variable
  const envPassphrase = process.env.AUTO_RESPAWN_PASSPHRASE
  if (envPassphrase) return envPassphrase

  // 2. Passphrase file
  const passphraseFilePath =
    process.env.AUTO_RESPAWN_PASSPHRASE_FILE || PASSPHRASE_FILE_DEFAULT
  try {
    const contents = await readFile(passphraseFilePath, 'utf-8')
    const trimmed = contents.trim()
    if (trimmed) return trimmed
  } catch {
    // File doesn't exist or can't be read — fall through
  }

  // 3. Interactive stdin prompt
  if (process.stdin.isTTY) {
    return new Promise<string>((resolve, reject) => {
      const rl = createInterface({ input: process.stdin, output: process.stderr })
      rl.question('Passphrase: ', (answer) => {
        rl.close()
        if (!answer) reject(new Error('No passphrase provided'))
        else resolve(answer)
      })
    })
  }

  throw new Error(
    'No passphrase found. Set AUTO_RESPAWN_PASSPHRASE env var, ' +
      'write it to ~/.openclaw/auto-respawn/.passphrase, ' +
      'or run interactively.',
  )
}

/**
 * Encrypt both keys (consensus + EVM) and persist the wallet file.
 *
 * Shared by createWallet and importWallet — any change to the file format,
 * encryption scheme, or stored fields only needs updating here.
 */
async function encryptAndSave(
  pair: KeyringPair,
  mnemonic: string,
  name: string,
  filepath: string,
  passphrase?: string,
): Promise<{ address: string; evmAddress: string }> {
  const resolved = await resolvePassphrase(passphrase)

  // Encrypt consensus key (Polkadot PKCS8: scrypt + XSalsa20-Poly1305)
  const keyringJson = pair.toJson(resolved)
  keyringJson.meta = { ...keyringJson.meta, name, whenCreated: Date.now() }

  // Derive EVM key and encrypt it via ethers V3 Keystore
  const evm = deriveEvmKey(mnemonic)
  const evmWallet = new ethers.Wallet(evm.privateKey)
  const evmKeystore = evmWallet.encryptSync(resolved)

  const walletFile: WalletFile = {
    keyring: keyringJson,
    evmAddress: evm.address,
    evmKeystore,
  }

  await writeFile(filepath, JSON.stringify(walletFile, null, 2), { mode: 0o600 })

  return { address: formatAddress(pair.address), evmAddress: evm.address }
}

export async function createWallet(name: string, passphrase?: string): Promise<CreatedWallet> {
  await cryptoWaitReady()
  await ensureWalletsDir()

  const filepath = keyfilePath(name)
  if (existsSync(filepath)) {
    throw new Error(`Wallet "${name}" already exists at ${filepath}`)
  }

  const wallet = sdkGenerateWallet()
  if (!wallet.keyringPair) throw new Error('Failed to generate wallet keypair')

  const { address, evmAddress } = await encryptAndSave(wallet.keyringPair, wallet.mnemonic, name, filepath, passphrase)

  return { name, address, evmAddress, mnemonic: wallet.mnemonic, keyfilePath: filepath }
}

export async function importWallet(name: string, mnemonic: string, passphrase?: string): Promise<WalletInfo> {
  await cryptoWaitReady()
  await ensureWalletsDir()

  const filepath = keyfilePath(name)
  if (existsSync(filepath)) {
    throw new Error(`Wallet "${name}" already exists at ${filepath}`)
  }

  const wallet = sdkSetupWallet({ mnemonic })
  if (!wallet.keyringPair) throw new Error('Failed to setup wallet keypair from mnemonic')

  const { address, evmAddress } = await encryptAndSave(wallet.keyringPair, mnemonic, name, filepath, passphrase)

  return { name, address, evmAddress, keyfilePath: filepath }
}

export async function listWallets(): Promise<WalletInfo[]> {
  await cryptoWaitReady()

  if (!existsSync(WALLETS_DIR)) return []

  const files = await readdir(WALLETS_DIR)
  const wallets: WalletInfo[] = []

  for (const file of files) {
    if (!file.endsWith('.json')) continue
    try {
      const filepath = join(WALLETS_DIR, file)
      const walletFile = await readWalletFile(filepath)
      const name = (walletFile.keyring.meta?.name as string) || file.replace('.json', '')
      const autonomysAddress = formatAddress(walletFile.keyring.address)
      wallets.push({
        name,
        address: autonomysAddress,
        evmAddress: walletFile.evmAddress,
        keyfilePath: filepath,
      })
    } catch {
      // Skip malformed files
    }
  }

  return wallets
}

/**
 * Load and decrypt a consensus keypair from a saved wallet.
 */
export async function loadWallet(name: string): Promise<KeyringPair> {
  await cryptoWaitReady()

  const filepath = keyfilePath(name)
  if (!existsSync(filepath)) {
    throw new Error(`Wallet "${name}" not found at ${filepath}`)
  }

  const walletFile = await readWalletFile(filepath)

  const keyring = new Keyring({ type: 'sr25519' })
  const pair = keyring.addFromJson(walletFile.keyring)

  const passphrase = await resolvePassphrase()
  try {
    pair.decodePkcs8(passphrase)
  } catch {
    throw new Error('Wrong passphrase — could not decrypt wallet')
  }

  return pair
}

/**
 * Get wallet info (both addresses) without decrypting. No passphrase needed.
 */
export async function getWalletInfo(name: string): Promise<WalletInfo> {
  await cryptoWaitReady()

  const filepath = keyfilePath(name)
  if (!existsSync(filepath)) {
    throw new Error(`Wallet "${name}" not found at ${filepath}`)
  }

  const walletFile = await readWalletFile(filepath)
  const autonomysAddress = formatAddress(walletFile.keyring.address)

  return {
    name,
    address: autonomysAddress,
    evmAddress: walletFile.evmAddress,
    keyfilePath: filepath,
  }
}

/**
 * Load a wallet's EVM address. No passphrase needed (stored in plaintext metadata).
 */
export async function loadEvmAddress(name: string): Promise<string> {
  const info = await getWalletInfo(name)
  return info.evmAddress
}

/**
 * Load and decrypt a wallet's EVM private key. Requires passphrase.
 * Uses ethers.js to decrypt the standard Ethereum V3 Keystore.
 */
export async function loadEvmPrivateKey(name: string): Promise<{ privateKey: string; address: string }> {
  const filepath = keyfilePath(name)
  if (!existsSync(filepath)) {
    throw new Error(`Wallet "${name}" not found at ${filepath}`)
  }

  const walletFile = await readWalletFile(filepath)

  const passphrase = await resolvePassphrase()
  try {
    const evmWallet = ethers.Wallet.fromEncryptedJsonSync(walletFile.evmKeystore, passphrase)
    return { privateKey: evmWallet.privateKey, address: walletFile.evmAddress }
  } catch {
    throw new Error('Wrong passphrase — could not decrypt EVM key')
  }
}

import { describe, it, expect } from 'vitest'
import { isConsensusAddress, isEvmAddress, normalizeAddress, normalizeEvmAddress } from '../lib/address.js'

// Known valid addresses for testing
const VALID_EVM = '0xd8dA6BF26964aF9D7eEd9e03E53415D37aA96045'
const VALID_EVM_LOWER = '0xd8da6bf26964af9d7eed9e03e53415d37aa96045'

// Derived from test mnemonic "test test test test test test test test test test test junk"
const VALID_SU_ADDRESS = 'sufmoyKii8Se1QaUz8wQSN9YBypcNtpi2d6XKPkpCxr3kZC5m'
const VALID_5_ADDRESS = '5GmS1wtCfR4tK5SSgnZbVT4kYw5W8NmxmijcsxCQE6oLW6A8'

describe('isConsensusAddress', () => {
  it('accepts valid su... address', () => {
    expect(isConsensusAddress(VALID_SU_ADDRESS)).toBe(true)
  })

  it('accepts valid 5... address', () => {
    expect(isConsensusAddress(VALID_5_ADDRESS)).toBe(true)
  })

  it('rejects EVM addresses', () => {
    expect(isConsensusAddress(VALID_EVM)).toBe(false)
  })

  it('rejects empty string', () => {
    expect(isConsensusAddress('')).toBe(false)
  })

  it('rejects random strings', () => {
    expect(isConsensusAddress('hello')).toBe(false)
  })
})

describe('isEvmAddress', () => {
  it('accepts valid checksummed EVM address', () => {
    expect(isEvmAddress(VALID_EVM)).toBe(true)
  })

  it('accepts valid lowercase EVM address', () => {
    expect(isEvmAddress(VALID_EVM_LOWER)).toBe(true)
  })

  it('rejects addresses without 0x prefix', () => {
    // Must require 0x prefix to stay consistent with normalizeEvmAddress
    expect(isEvmAddress('d8dA6BF26964aF9D7eEd9e03E53415D37aA96045')).toBe(false)
  })

  it('rejects too-short addresses', () => {
    expect(isEvmAddress('0x1234')).toBe(false)
  })

  it('rejects empty string', () => {
    expect(isEvmAddress('')).toBe(false)
  })

  it('rejects consensus addresses', () => {
    expect(isEvmAddress('su1234567890')).toBe(false)
  })
})

describe('normalizeAddress', () => {
  it('passes through a valid su... address', () => {
    const result = normalizeAddress(VALID_SU_ADDRESS)
    expect(result).toBe(VALID_SU_ADDRESS)
  })

  it('converts a 5... address to su... format', () => {
    const result = normalizeAddress(VALID_5_ADDRESS)
    expect(result).toMatch(/^su/)
    // Both formats represent the same public key, so normalising the 5... address
    // should produce the same su... address
    expect(result).toBe(VALID_SU_ADDRESS)
  })

  it('throws on EVM addresses', () => {
    expect(() => normalizeAddress(VALID_EVM)).toThrow(/Invalid address prefix/)
  })

  it('throws on random strings', () => {
    expect(() => normalizeAddress('hello')).toThrow(/Invalid address prefix/)
  })

  it('throws on address with valid prefix but invalid encoding', () => {
    expect(() => normalizeAddress('su00000000000000000000')).toThrow(/Could not decode/)
  })
})

describe('normalizeEvmAddress', () => {
  it('checksums a valid lowercase address', () => {
    const result = normalizeEvmAddress(VALID_EVM_LOWER)
    expect(result).toBe(VALID_EVM)
  })

  it('passes through an already-checksummed address', () => {
    const result = normalizeEvmAddress(VALID_EVM)
    expect(result).toBe(VALID_EVM)
  })

  it('throws on missing 0x prefix', () => {
    expect(() => normalizeEvmAddress('d8dA6BF26964aF9D7eEd9e03E53415D37aA96045'))
      .toThrow(/Expected an address starting with 0x/)
  })

  it('throws on invalid hex', () => {
    expect(() => normalizeEvmAddress('0xZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZ'))
      .toThrow(/Not a valid Ethereum address/)
  })
})

import { describe, it, expect, vi } from 'vitest'
import type { BalanceResult } from '../lib/balance.js'

/**
 * Balance formatting tests.
 *
 * Mocks the @autonomys/auto-consensus `balance()` function to avoid
 * needing a real RPC connection. Tests that queryBalance correctly
 * normalises addresses, formats shannons → AI3, and labels the network.
 */

// Mock the consensus balance call — returns raw bigint values
vi.mock('@autonomys/auto-consensus', () => ({
  balance: vi.fn(),
}))

// We need to import after mocking
const { balance: mockBalance } = await import('@autonomys/auto-consensus')
const { queryBalance } = await import('../lib/balance.js')

// A valid su... address derived from the well-known test mnemonic
// "test test test test test test test test test test test junk"
const TEST_ADDRESS = 'sufmoyKii8Se1QaUz8wQSN9YBypcNtpi2d6XKPkpCxr3kZC5m'

describe('queryBalance', () => {
  it('formats shannons to AI3 correctly for non-zero balances', async () => {
    vi.mocked(mockBalance).mockResolvedValue({
